import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 73 · Everyday recipe: old-fashioned banana bread (Google Trends 3/11: easy baking recipes, banana bread evergreen)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, there's a bunch of bananas on your counter right now going brown and spotty, and you're about to throw them away. Don't you dare. Those ugly black bananas are worth more than the pretty yellow ones. They make the best banana bread in the world, the kind that's moist and dark and sweet, and fills the whole house with the smell of a grandmother's kitchen.""",
   "overripe brown bananas on counter", "DON'T THROW THEM AWAY")
sc("""But people tell me their banana bread comes out dry, or pale, or sunk in the middle, or gummy at the bottom. So tonight I'm giving you my mother's banana bread, step by step, and the five mistakes that ruin it. And stay with me, because the last secret is a trick with the bananas that most people have never heard of, and it doubles the flavor.""",
   "sunken banana bread loaf", "WHY YOURS IS DRY")

ch("A Depression recipe")
sc("""Banana bread is younger than you'd think, honey. It became popular in the nineteen thirties, during the Great Depression. Baking powder and baking soda were cheap and everywhere, and nobody could afford to throw away a single banana. So the housewives of America turned the spotted ones into a sweet loaf. Pillsbury put it in their cookbook in nineteen thirty-three, and it never went away.""",
   "1930s housewife kitchen baking", "NOTHING THROWN AWAY")
sc("""My mother learned it from her mother during those hard years, and she never stopped making it. When I was a girl on Elm Street, there was always a loaf wrapped in wax paper in the bread box. Danny ate it for breakfast, I ate it after school, and my father took two thick slices in his lunch pail to the plant every single day. In a minute I'll tell you the mistake almost everybody makes.""",
   "vintage bread box wax paper loaf", "ALWAYS IN THE BREAD BOX")
sc("""And there was a rule in our house. Nobody was allowed to eat a banana that had a single brown spot on it. My mother would snatch it right out of your hand and say, that one's for the bread. She kept them in a paper sack on top of the icebox, and when there were three, she baked. To this day, I can't eat a spotty banana.""",
   "bananas in paper bag kitchen", "THAT ONE'S FOR THE BREAD")

ch("What you need")
sc("""Here's what you need for one loaf. Three very ripe bananas, the blacker the better. One third of a cup of melted butter. Three quarters of a cup of brown sugar. One egg. One teaspoon of vanilla. One teaspoon of baking soda, a pinch of salt, half a teaspoon of cinnamon. And one and a half cups of all-purpose flour. That's it. One bowl, and no mixer.""",
   "banana bread ingredients flour butter eggs", "ONE BOWL")
sc("""And here's mistake number one. Bananas that aren't ripe enough. A yellow banana with a few freckles has starch in it, not sugar, and it makes a pale, bland, dry loaf. You want bananas that are mostly brown or black, soft to the touch, and smell sweet. That's when all the starch has turned into sugar, and that's where the flavor and the moisture come from.""",
   "yellow banana vs black banana", "THE BLACKER THE BETTER")
sc("""And if your bananas are still yellow and you need bread today, here's my trick. Put them, peel and all, on a baking sheet in a three hundred degree oven for about fifteen to twenty minutes, until the skins turn shiny and black. Let them cool. They'll be soft and sweet inside. It's not quite as good as waiting, but it's close.""",
   "bananas roasting in oven black skins", "THE OVEN TRICK")

ch("Mixing it")
sc("""Heat your oven to three hundred fifty, and grease a nine by five loaf pan. Peel the bananas into a big bowl and mash them with a fork. Leave a few little lumps, honey. Those lumps turn into sweet, soft pockets of banana in the bread. Stir in the melted butter. Then the brown sugar, the egg and the vanilla, until it's all mixed together.""",
   "mashing bananas with fork bowl", "LEAVE A FEW LUMPS")
sc("""And here's mistake number two. Using white sugar and oil. White sugar makes it sweet, but brown sugar makes it taste like caramel, and it keeps the loaf moist for days. And butter gives it a flavor that oil never will. My mother tried bacon grease once, in nineteen fifty-two, when the butter ran out on a Sunday. Danny still talks about it, and not in a good way.""",
   "brown sugar melted butter bowl", "BROWN SUGAR AND BUTTER")
sc("""If this is helping you, sweetheart, tap the like button for me. It helps Grandma more than you know. Now sprinkle the baking soda, salt and cinnamon right over the wet mixture, and stir it in well. Then add the flour, and here's mistake number three. Overmixing. Fold it in gently with a spatula, only until the last streak of flour disappears. Lumpy batter is perfect.""",
   "folding flour into banana batter spatula", "LUMPY IS PERFECT")
sc("""When you stir flour too much, it builds up the gluten, the same stretchy stuff that makes bread chewy. In a yeast bread, that's what you want. In a quick bread, it makes a tough, rubbery loaf with tunnels running through it. Twelve to fifteen strokes with the spatula, honey, and stop. If you want walnuts or chocolate chips, fold in a half cup now.""",
   "banana bread slice with walnuts", "FIFTEEN STROKES")

ch("Baking it")
sc("""Pour the batter into the pan and smooth the top. Here's a little bakery trick. Slice one more banana in half the long way, and lay the two halves on top, cut side up. Sprinkle a tablespoon of sugar over the whole top. It bakes into a crackly, golden crust with a pretty banana on top. People will think you bought it at a fancy bakery.""",
   "banana halves on top of loaf batter", "THE BAKERY TOP")
sc("""Bake for fifty-five to sixty-five minutes. And here's mistake number four. Taking it out too early. A banana bread looks done on the outside long before the middle is cooked. That's why it sinks and gets gummy. Stick a toothpick right into the center. It should come out with a few moist crumbs, not wet batter. If the top browns too fast, lay a piece of foil loosely over it.""",
   "toothpick in center of banana bread", "CHECK THE CENTER")
sc("""And use a metal pan if you can, honey, not glass. A glass pan gets very hot, and the sides and bottom burn before the middle bakes. If glass is all you have, turn your oven down twenty-five degrees and bake it a little longer. My mother's old tin loaf pan was black and dented, and it made the best banana bread in Mansfield for fifty years.""",
   "old dented metal loaf pan", "METAL, NOT GLASS")

sc("""When I was nine, honey, I made my first banana bread all by myself, for my father's birthday. I forgot the baking soda. It came out of the oven flat as a board and heavy as a brick. My father ate two slices anyway, and told me it was the best thing he ever tasted. Then he used the rest to prop open the garage door for a week.""",
   "flat dense loaf on plate 1950s kitchen", "FLAT AS A BOARD")
ch("The secret")
sc("""Now the secret I promised you, the trick with the bananas. Before you mash them, put the peeled bananas in a bowl and microwave them for about three minutes, until they let go of a lot of juice. Pour them into a strainer over a little pot, and let the juice drip out for ten minutes. You'll get about half a cup of banana liquid.""",
   "banana juice in strainer pot", "THE BANANA JUICE")
sc("""Boil that juice in the little pot for about five minutes, until it's down to a couple of tablespoons of thick banana syrup. Then stir it back into the mashed bananas. Now your batter isn't watery, and all the banana flavor is concentrated, twice as strong. It's the difference between a banana bread that tastes nice and one that tastes like bananas. My granddaughter found that trick in a magazine, and I'll admit it beat my mother's.""",
   "reducing syrup in small pot", "TWICE THE FLAVOR")

sc("""And if you don't have bananas ready today, sweetheart, here's what my mother did. Whenever a banana got too spotty, she peeled it and put it in the freezer in a jar. When she had three, she thawed them on the counter for an hour. They come out soft and brown and swimming in juice, which is perfect for the syrup trick. Never throw away another banana as long as you live.""",
   "frozen peeled bananas in jar", "INTO THE FREEZER")
ch("Cooling and keeping")
sc("""And mistake number five. Cutting it hot. I know it smells wonderful, sweetheart, but let it cool in the pan for ten minutes, then turn it out onto a rack and let it cool for at least an hour. A hot banana bread is still setting inside, and if you cut it, it squishes and goes gummy. Wait, and every slice will be perfect.""",
   "banana bread cooling on wire rack", "WAIT AN HOUR")
sc("""Wrap it in plastic wrap or wax paper, and keep it on the counter. It's even better the next day, moister and more banana-y. It keeps for four days, and it freezes beautifully for three months. I slice it first, put wax paper between the slices, and freeze them. Then I toast a slice straight from the freezer with a little butter. That's breakfast fit for a queen.""",
   "toasted banana bread slice butter", "FIT FOR A QUEEN")

ch("Grandma's kitchen")
sc("""So one more time. Bananas that are black and soft. Brown sugar and butter. Leave a few lumps, and don't overmix. Bake it until the center is done, in a metal pan. Boil the banana juice down for twice the flavor. And let it cool before you cut it. That's banana bread the way my mother made it during the hard years, and it's never been beat.""",
   "homemade banana bread loaf sliced", "NEVER BEEN BEAT")
sc("""Tell me in the comments, sweetheart. Walnuts, chocolate chips, or plain? I want to know which team you're on. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "banana bread kitchen table coffee", "WHICH TEAM ARE YOU?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma73", "Banana Bread EVERYONE's Grandma Made (Why Yours Is DRY and Sunken)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Banana bread became popular in the US in the 1930s with the spread of baking soda and baking powder; it appeared in Pillsbury's Balanced Recipes cookbook in 1933.",
      "Recipe as written by Grandma Ruth: 3 very ripe bananas, 1/3 cup melted butter, 3/4 cup brown sugar, 1 egg, 1 tsp vanilla, 1 tsp baking soda, pinch of salt, 1/2 tsp cinnamon, 1 1/2 cups flour; 9x5 metal pan at 350F for 55-65 minutes."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
